289	                        .content(rescheduleBody(key("REQ"), newKey, 1, 1)))
290	                .andExpect(status().isUnprocessableEntity()).andReturn();
291	        JsonNode error = read(result);
292	        assertThat(error.get("code").asText()).isEqualTo("SLOT_CONFLICT");
293	        assertThat(error.get("details").get(0).get("type").asText()).isEqualTo("TRAIN_OVERLAP");
294	
295	        // 回滚：旧计划仍发布、新计划仍草稿、无关联、时隙仍归旧计划
296	        assertRolledBack(oldKey, newKey, section);
297	    }
